 string BlueprintDescription(BuildDefinition d)=>d.Function switch{"structure"=>$"Load capacity {d.Capacity:0}; condition {d.Durability:0}. Requires ground contact or structural support.","door"=>d.Opening!=""?"Aim at the door or gate and press F. Manual operation at every tier; swings away from you. Keep the swing clear.":"F opens/closes. Tier 4+ doors require nearby power.","window"=>"A real open window with a sill and solid frame. Aim through the aperture; advanced tiers have a metal mullion.","storage"=>"Shared storage for resources, supplies and ammunition.","fridge"=>"Shared storage; powered refrigeration prevents stored food spoilage.","power"=>"Fuel with fiber and resin; supplies equipment within 24m.","vehicle" or "mobile"=>"F enters driver seat. WASD drives; F dismounts. Trailer provides rest.","medical"=>"Powered dressing production and improved slow recovery nearby. Wound timers remain 20 minutes.","water"=>"Produces drinking water every two active minutes. Collect with F.","food" or "farm"=>"Produces food over active playtime. Tier 4+ needs nearby power.","turret"=>"Load reserve ammunition with F. Attacks hostile targets; Tier 5 requires power.","electric" or "electrictrap"=>"Powered perimeter defense damages nearby hostile enemies.",_=>"Place with B. F shows its functions, supplies and repairs."};
