 void CycleBlueprint(int direction){var available=ExpeditionRecipe.All.Where(r=>r.Kind=="build"&&game.Knows(r)&&game.ResearchAccess(r)=="Unlocked").Select(r=>r.Result).ToArray();if(available.Length==0)return;int i=Array.IndexOf(available,selectedBuild);selectedBuild=available[(i+direction+available.Length)%available.Length];}
